// <auto-generated/>
namespace Fanex.Tarus.Finance.Controller.Customer
{
    using System.Collections.Generic;
    using System.Web.Mvc;
    using Fanex.Tarus.Finance.Business.Customer;
    using Fanex.Tarus.Finance.Model;
    using Fanex.Tarus.Web.Controllers;

    public class FinanceCustomerListController : BaseController
    {
        private readonly IFinanceCustomerListService _financeCustomerListService;

        public FinanceCustomerListController()
        {
            _financeCustomerListService = new FinanceCustomerListService();
        }

        public ActionResult Index(long? upline, int? roleid)
        {
            if (roleid == null)
            {
                roleid = 4;
                ViewData["roleid"] = roleid;
            }
            else
            {
                roleid -= 1;
                ViewData["roleid"] = roleid;
            }
            ViewData["upline"] = upline == null ? 0 : upline;
            return View("~/Views/Finance/Customer/Index.cshtml");
        }

        public JsonResult GetCustomerList(List<PostParam> postParams, int roleId)
        {
            Model.Customer.CustomerList customerList = new Model.Customer.CustomerList();
            switch (roleId)
            {
                case 4:
                    customerList = _financeCustomerListService.GetSuperList(postParams);
                    break;

                case 3:
                    customerList = _financeCustomerListService.GetMasterList(postParams);
                    break;

                case 2:
                    customerList = _financeCustomerListService.GetAgentList(postParams);
                    break;

                case 1:
                    customerList = _financeCustomerListService.GetMemberList(postParams);
                    break;
            }
            return Json(customerList, JsonRequestBehavior.AllowGet);
        }
    }
}